#[path = "/home/brittonr/git/OnixResearch/trellis/src/snapshot_integrity.rs"]
mod snapshot_integrity;

use snapshot_integrity::{SnapshotIntegrity, combine_hashes, compute_integrity, verify_integrity, verify_with_chain_hash};

fn main() {
    let mut component_rejections = 0;
    let mut commitment_rejections = 0;
    let boundaries = [0, 1, 1_u64 << 63, u64::MAX];
    for data in boundaries {
        for meta in boundaries {
            let original = compute_integrity(data, meta, 17);
            assert!(verify_integrity(&original));
            assert!(verify_with_chain_hash(&original, 17));
            assert!(!verify_with_chain_hash(&original, 18));
            for bit in 0..64 {
                let data_tamper = SnapshotIntegrity { data_hash: data ^ (1_u64 << bit), ..compute_integrity(data, meta, 17) };
                assert!(!verify_integrity(&data_tamper));
                assert!(!verify_with_chain_hash(&data_tamper, 17));
                let meta_tamper = SnapshotIntegrity { meta_hash: meta ^ (1_u64 << bit), ..compute_integrity(data, meta, 17) };
                assert!(!verify_integrity(&meta_tamper));
                assert!(!verify_with_chain_hash(&meta_tamper, 17));
                component_rejections += 2;
            }
            for bit in 0..128 {
                let combined_tamper = SnapshotIntegrity { combined_hash: original.combined_hash ^ (1_u128 << bit), ..compute_integrity(data, meta, 17) };
                assert!(!verify_integrity(&combined_tamper));
                assert!(!verify_with_chain_hash(&combined_tamper, 17));
                commitment_rejections += 1;
            }
            let consistent_new_record = compute_integrity(data ^ 1, meta ^ 1, 17);
            assert!(verify_integrity(&consistent_new_record));
        }
    }
    assert_ne!(combine_hashes(0, 0), combine_hashes(0, 1_u64 << 63));
    assert_ne!(combine_hashes(1, 0), combine_hashes(0, 1));
    let mut former_collision = compute_integrity(0, 0, 17);
    former_collision.meta_hash = 1_u64 << 63;
    assert!(!verify_integrity(&former_collision));
    assert!(!verify_with_chain_hash(&former_collision, 17));
    println!("{{\"boundary_pairs\":16,\"component_tamper_rejections\":{component_rejections},\"commitment_tamper_rejections\":{commitment_rejections},\"former_collision_rejected\":true,\"matching_chain_accepted\":true,\"wrong_chain_rejected\":true,\"recomputed_record_verifies_without_authentication_claim\":true}}");
}
